/*getMenuPermission*/
SELECT NVL(MAX(A.READ_YSNO), #{no}) AS READ_YSNO
     , NVL(MAX(A.WRIT_YSNO), #{no}) AS WRIT_YSNO
     , NVL(MAX(A.DELT_YSNO), #{no}) AS DELT_YSNO
  FROM TM_ADMENU M
  JOIN TB_AUTHMN A
    ON A.MENU_NUMB = M.MENU_NUMB
   AND A.SUBX_NUMB = M.SUBX_NUMB
   AND A.AUTH_CODE = #{authCode}
  JOIN TM_AUTHXM G
    ON G.AUTH_CODE = A.AUTH_CODE
   AND NVL(G.USEE_YSNO, #{yes}) = #{yes}
 WHERE TRIM(M.MENU_URLX) = #{menuUrlx}



/*getMenuDtl*/
SELECT 
  FROM TM_ADMENU
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}

  /*getSubMenuList*/



  SELECT 
    FROM TM_ADMENU
   WHERE MENU_NUMB = #{menuNumb}
     AND SUBX_NUMB != #{topMenuSubxNumb}
ORDER BY NVL(SORT_ORDR, 9999) DESC

/*getMenuNumb*/

SELECT TO_CHAR(NVL(MAX(TO_NUMBER(MENU_NUMB)), 0) + 1)
  FROM TM_ADMENU
 WHERE SUBX_NUMB = #{topMenuSubxNumb}

/*getSubxNumb*/
SELECT TO_CHAR(NVL(MAX(TO_NUMBER(SUBX_NUMB)), -1) + 1)
  FROM TM_ADMENU
 WHERE MENU_NUMB = #{menuNumb}

