/*setMenuAuth*/
INSERT INTO TB_AUTHMN (
                         AUTH_CODE
                       , MENU_NUMB
                       , SUBX_NUMB
                       , READ_YSNO
                       , WRIT_YSNO
                       , DELT_YSNO
                       , REGI_ADMN
                       , REGI_DATE
                       , UPDT_ADMN
                       , UPDT_DATE
            )
SELECT A.AUTH_CODE
     , #{menuNumb}
     , #{subxNumb}
     , #{yes}
     , #{yes}
     , #{yes}
     , #{regiAdmn}
     , SYSTIMESTAMP
     , #{updtAdmn}
     , SYSTIMESTAMP
  FROM TM_AUTHXM A

mapper.update:
/*uptMenu*/
UPDATE TM_ADMENU
   SET MENU_NAME = #{menuName}
     , MENU_URLX = #{menuUrlx}
     , SORT_ORDR = #{sortOrdr}
     , USEE_YSNO = #{useeYsno}
     , UPDT_ADMN = #{updtAdmn}
     , UPDT_DATE = SYSTIMESTAMP
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}

mapper.delete:
/*delMenu*/
DELETE FROM TM_ADMENU
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}

/*delMenuAuth*/
DELETE FROM TB_AUTHMN
 WHERE MENU_NUMB = #{menuNumb}
   AND SUBX_NUMB = #{subxNumb}
